class Solution {
    public int numOfSubarrays(int[] arr){
        long even=1,odd=0,answer=0,mod=1_000_000_007L;
        int parity=0;
        for(int value:arr){
            parity^=value&1;
            if(parity==0){
                answer+=odd;
                even++;
            }else{
                answer+=even;
                odd++;
            }
            answer%=mod;
        }
        return (int)answer;
    }
}

code.kotlin:
class Solution {
    fun numOfSubarrays(arr:IntArray):Int{
        val mod=1_000_000_007L;
        var even=1L;
        var odd=0L;
        var answer=0L;
        var parity=0;
        for(value in arr){
            parity=parity xor (value and 1);
            if(parity==0){
                answer+=odd;
                even++
            }else{
                answer+=even;
                odd++
            };
            answer%=mod
        };
        return answer.toInt()
    }
}

code.cpp:
class Solution {
    public: int numOfSubarrays(vector<int>& arr){
        const long long mod=1000000007;
        long long even=1,odd=0,answer=0;
        int parity=0;
        for(int value:arr){
            parity^=value&1;
            if(!parity){
                answer+=odd;
                ++even;
            }else{
                answer+=even;
                ++odd;
            }
            answer%=mod;
        }
        return answer;
    }
};
